// Entwürfe aufteilen (Stefan 18.10.2026): ein Eintrag je offenem Entwurf aus talents_mail_entwuerfe_holen()
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Mail-Entwürfe: ' + String(r.fehler || 'nicht lesbar').slice(0, 200));
const test = $execution.mode !== 'production';
return (Array.isArray(r.entwuerfe) ? r.entwuerfe : []).filter(e => e && Number(e.id) > 0).map(e => ({ json: Object.assign({}, e, { test }) }));

// Anhänge vorbereiten (Stefan 18.10.2026): je Anhang ein Auftrag "holen" an TALENTS Ablage, ohne Anhang ein Auftrag "keine"
const e = $input.first().json;
const a = Array.isArray(e.anhaenge) ? e.anhaenge.filter(x => x && Number(x.datei_id) > 0) : [];
if (!a.length) return [{ json: { aktion: 'keine', entwurf_id: e.id } }];
return a.slice(0, 5).map(x => ({ json: { aktion: 'holen', datei_id: Number(x.datei_id), entwurf_id: e.id } }));

// Entwurf bauen (Stefan 18.10.2026): Mail im Format RFC 822 wie ALLY 6 (Signatur des Postfachs mit {Name}, keine festen Farben, Schrift des
// Postfachs, Platzhalter [..] rot, KI-Hinweis nach Einstellung) und mit PDF-Anhängen (multipart/mixed). Ally legt nur den Entwurf ab.
const r = $('Je Entwurf').first().json;
const items = $input.all();
const anhaenge = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  if (j.keine === true) continue;
  if (j.ok !== true || !items[i].binary || !items[i].binary.datei) throw new Error('Ein Anhang konnte nicht geholt werden: ' + String(j.fehler || 'unbekannt').slice(0, 200));
  const buf = await this.helpers.getBinaryDataBuffer(i, 'datei');
  anhaenge.push({ name: String(j.name || items[i].binary.datei.fileName || 'Anhang.pdf'), mime: String(j.mime || items[i].binary.datei.mimeType || 'application/pdf'), buf });
}
const erwartet = Array.isArray(r.anhaenge) ? r.anhaenge.length : 0;
if (anhaenge.length !== erwartet) throw new Error('Es fehlen Anhänge (' + anhaenge.length + ' von ' + erwartet + ').');
if (anhaenge.reduce((s, a) => s + a.buf.length, 0) > 15 * 1024 * 1024) throw new Error('Die Anhänge sind zusammen größer als 15 MB.');

const body = String(r.text || '').replace(/\r/g, '').trim();
if (!body) throw new Error('Der Entwurf hat keinen Text.');
const postfach = String(r.postfach || '').trim().toLowerCase();
if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(postfach)) throw new Error('Ungültiges Postfach.');
const name = String(r.signatur_name || '').trim();
if (!name && (/\{Name\}/.test(String(r.signatur_html || '')) || /\{Name\}/.test(String(r.signatur_text || '')))) throw new Error('Für die Signatur ist kein Name hinterlegt (Meine Einstellungen). Entwurf wurde nicht angelegt.');
const SCHRIFT = String(r.schrift_stapel || 'Helvetica Neue, Helvetica, Arial, sans-serif').replace(/["'<>;]/g, '');
const GROESSE = Number(r.schrift_groesse) >= 10 && Number(r.schrift_groesse) <= 20 ? Number(r.schrift_groesse) : 13;
const schriftStil = 'font-family: ' + SCHRIFT + '; font-size: ' + GROESSE + 'px;';
const ohneFarbe = h => String(h || '')
  .replace(/\sstyle\s*=\s*(["'])([\s\S]*?)\1/gi, (m, q, s) => {
    const rest = s.split(';').map(x => x.trim()).filter(x => x && !/^(color|background|background-color)\s*:/i.test(x)).map(x => /^font-size\s*:/i.test(x) ? 'font-size: ' + GROESSE + 'px' : (/^font-family\s*:/i.test(x) ? 'font-family: ' + SCHRIFT : x)).join('; ');
    return rest ? ' style=' + q + rest + ';' + q : '';
  })
  .replace(/\s(color|bgcolor|text|link|vlink|alink|face|size)\s*=\s*(["'])[^"']*\2/gi, '');
const esc = s => String(s ?? '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const sigText = String(r.signatur_text || '').trim().replace(/\{Name\}/g, name);
const sigHtml = ohneFarbe(String(r.signatur_html || '').trim()).replace(/\{Name\}/g, esc(name));
const ROT = '#D00000';
const pStyle = 'margin:0 0 12pt 0; ' + schriftStil;
const htmlBody = body.split(/\n{2,}/).map(p => '<p style="' + pStyle + '">' + esc(p).split('\n').join('<br>')
  .replace(/\[([^\[\]\n<>]{1,150})\]/g, '<span style="color: ' + ROT + ';">[$1]</span>') + '</p>').join('');
const KI = r.ki_hinweis === true ? 'Erstellt mit KI-Unterstützung.' : '';
const fullText = body + (sigText ? '\n\n' + sigText : '') + (KI ? '\n\n' + KI : '');
const fullHtml = '<html><head><meta charset="utf-8"></head><body><div style="direction: ltr; ' + schriftStil + '">' + htmlBody + '</div>'
  + (sigHtml ? '<div style="' + schriftStil + '">' + sigHtml + '</div>' : '')
  + (KI ? '<div style="' + schriftStil + '"><p style="margin:12pt 0 0 0; ' + schriftStil + '">' + KI + '</p></div>' : '') + '</body></html>';
if (/\{Name\}/.test(sigHtml + sigText)) throw new Error('Signatur enthält noch den Platzhalter {Name}. Entwurf wurde nicht angelegt.');

const ascii = s => /^[\x20-\x7e]*$/.test(s);
const word = s => ascii(s) ? s : '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=';
const addr = (n, m) => n ? (ascii(n) ? '"' + n.replace(/"/g, '') + '"' : word(n)) + ' <' + m + '>' : m;
const b64 = buf => Buffer.from(buf).toString('base64').replace(/(.{76})/g, '$1\r\n');
const winkel = id => { const t = String(id || '').trim(); return !t ? '' : (t.startsWith('<') ? t : '<' + t + '>'); };
const dateiname = n => { const s = String(n).replace(/[\r\n"\\]/g, '').slice(0, 150) || 'Anhang.pdf'; return ascii(s) ? '"' + s + '"' : '"' + word(s) + '"'; };
const an = String(r.an || '').trim();
if (an && !/^[^@\s<>"]+@[^@\s<>"]+\.[a-z]{2,}$/i.test(an)) throw new Error('Ungültige Empfängeradresse.');
const betreff = String(r.betreff || '').replace(/[\r\n]+/g, ' ').trim();
const inReplyTo = winkel(r.message_id);
const refs = [String(r.referenzen || '').trim(), inReplyTo].filter(Boolean).join(' ');
const zufall = () => Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const grenzeAlt = 'ally-alt-' + zufall();
const grenzeMix = 'ally-mix-' + zufall();
const msgId = '<ally-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '@' + (postfach.split('@')[1] || 'ally.invalid') + '>';
const alternativ = [
  '--' + grenzeAlt, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', b64(Buffer.from(fullText, 'utf8')),
  '--' + grenzeAlt, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', b64(Buffer.from(fullHtml, 'utf8')),
  '--' + grenzeAlt + '--'];
const kopf = [
  'From: ' + addr(String(r.absender_name || '').trim(), postfach),
  an ? 'To: ' + addr(String(r.an_name || '').trim(), an) : null,
  'Subject: ' + word(betreff),
  'Date: ' + new Date().toUTCString().replace('GMT', '+0000'),
  'Message-ID: ' + msgId,
  inReplyTo ? 'In-Reply-To: ' + inReplyTo : null,
  refs ? 'References: ' + refs : null,
  'MIME-Version: 1.0'].filter(z => z !== null);
let zeilen;
if (!anhaenge.length) {
  zeilen = kopf.concat(['Content-Type: multipart/alternative; boundary="' + grenzeAlt + '"', ''], alternativ, ['']);
} else {
  zeilen = kopf.concat(['Content-Type: multipart/mixed; boundary="' + grenzeMix + '"', '', '--' + grenzeMix,
    'Content-Type: multipart/alternative; boundary="' + grenzeAlt + '"', ''], alternativ, ['']);
  for (const a of anhaenge) {
    zeilen = zeilen.concat(['--' + grenzeMix, 'Content-Type: ' + a.mime.replace(/[^a-z0-9.+\/-]/gi, '') + '; name=' + dateiname(a.name),
      'Content-Transfer-Encoding: base64', 'Content-Disposition: attachment; filename=' + dateiname(a.name), '', b64(a.buf)]);
  }
  zeilen = zeilen.concat(['--' + grenzeMix + '--', '']);
}
return [{ json: { id: r.id, postfach, ordner: String(r.ordner || 'Entwürfe'), rfc822: zeilen.join('\r\n'), test: r.test === true, anhaenge: anhaenge.length } }];

// Fehler beim Bauen oder Ablegen (Stefan 18.10.2026): Grund für talents_mail_entwurf_ergebnis
const r = $('Je Entwurf').first().json;
const e = $input.first().json.error;
return [{ json: { id: r.id, test: r.test === true, fehler: String((e && (e.message || e.description)) || e || 'Der Entwurf konnte nicht abgelegt werden.').slice(0, 300) } }];

// Mail für Versand (TALENTS Mail-Entwürfe, Plan 57, Migration 192): vorgemerkte Einladung über ein Postfach (versand senden). Mail mit Link, Empfänger, Postfach,
// (Unterablauf „Aufruf“ prüft Nummer, an und von). Testlauf (nicht production): nichts senden, nur Vorschau (Muster MAIL 4 _test). Passt etwas nicht: Fehlergrund.
const r = $('Je Entwurf').first().json;
const s = v => String(v ?? '');
const MAIL = /^[^\s@<>"',;]{1,64}@[^\s@<>"',;]{1,190}$/;
if (!Number.isInteger(Number(r.nr)) || Number(r.nr) < 1) throw new Error('Postfach-Platz fehlt. Nichts gesendet.');
if (!/^[A-Za-z0-9]{8,40}$/.test(s(r.workflow_id))) throw new Error('Workflow des Postfachs fehlt. Nichts gesendet.');
if (!MAIL.test(s(r.an)) || !MAIL.test(s(r.von))) throw new Error('Empfänger oder Absender ungültig. Nichts gesendet.');
const betreff = s(r.betreff).replace(/[\r\n]+/g, ' ').trim().slice(0, 200);
if (!betreff || !s(r.text).trim() || !s(r.html).trim()) throw new Error('Die Mail ist unvollständig. Nichts gesendet.');
if (!/https:\/\/[^\s"<>]+/.test(s(r.text))) throw new Error('Die Mail enthält keinen Einladungslink. Nichts gesendet.');
const name = s(r.von_name).replace(/[<>"\\,;:()\r\n\t]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 80);
return [{ json: { id: Number(r.id), test: r.test === true, senden: r.test !== true, aktion: 'senden', nr: Number(r.nr), workflow_id: s(r.workflow_id),
  von: name ? '"' + name + '" <' + s(r.von) + '>' : s(r.von), an: s(r.an), betreff, text: s(r.text), html: s(r.html), anhaenge: '' } }];

// Versand auswerten (TALENTS Mail-Entwürfe, Plan 57, Migration 192): Ergebnis von „MAIL Postfach Nr. n“ (Knoten „Senden“, Fehler als Eintrag) wie SYS 9 – gesendet nur,
// wenn der Mailserver die Adresse angenommen hat. Testlauf: nichts gesendet, die Einladung bleibt vorgemerkt. Kein zweiter Versuch (talent_einladung_versand_ergebnis).
const v = $('Mail für Versand').first().json;
const j = $input.first().json || {};
const t = x => String(x ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
if (v.test === true) return [{ json: { id: v.id, ok: false, test: true, fehler: '' } }];
let ok = false, fehler = '';
if (j.error) fehler = t((j.error && (j.error.message || j.error.description)) || j.error) || 'Versand fehlgeschlagen.';
else if (Array.isArray(j.rejected) && j.rejected.length) fehler = 'Vom Mailserver abgelehnt: ' + t(j.rejected.join(', '));
else if ((Array.isArray(j.accepted) && j.accepted.length) || j.messageId) ok = true;
else fehler = 'Keine Bestätigung vom Mailserver.';
return [{ json: { id: v.id, ok, test: false, fehler } }];

