-- Ergebnis des Versands einer Einladung über ein Postfach (Plan 57, Migration 192): gesendet bzw. Fehler ohne neuen Versuch (Benachrichtigung);
-- Testlauf: nichts gesendet, bleibt vorgemerkt.
SELECT talents_mail_entwurf_ergebnis($1::integer, $2::boolean, NULLIF($3::text, ''), $4::boolean) AS r;
